def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Apply reviewed gold citation overrides to workbook.")
    parser.add_argument("--input", default="tests/benchmarks/Полный бенчмарк-3.normalized.xlsx")
    parser.add_argument("--output", default="tests/benchmarks/Полный бенчмарк-3.reviewed.xlsx")
    parser.add_argument("--sheet", default="Benchmark")
    return parser.parse_args()


def clean_text(value: object) -> str:
    if value is None:
        return ""
    return " ".join(str(value).replace("\xa0", " ").split()).strip()


def main() -> None:
    args = parse_args()
    input_path = Path(args.input)
    wb = load_workbook(input_path)
    ws = wb[args.sheet]
    headers = [clean_text(v) for v in next(ws.iter_rows(min_row=1, max_row=1, values_only=True))]
    gold_col = headers.index("gold_citations") + 1

    for row_number, citation in OVERRIDES.items():
        ws.cell(row_number, gold_col).value = citation

    output_path = Path(args.output)
    output_path.parent.mkdir(parents=True, exist_ok=True)
    wb.save(output_path)
    print(f"Saved reviewed workbook: {output_path}")
    print(f"Overrides applied: {len(OVERRIDES)}")


if __name__ == "__main__":
    main()
